function renderStats(){const n=document.getElementById("stats-grid");n&&"undefined"!=typeof LALITADITYA_INFO&&(n.innerHTML=LALITADITYA_INFO.quickStats.map(n=>`\n        <div class="stat-card">\n            <span class="stat-icon">${n.icon}</span>\n            <div class="stat-val">${n.value}</div>\n            <div class="stat-lbl">${n.label}</div>\n        </div>\n    `).join(""))}function renderMartandCard(){const n=document.getElementById("martand-card");n&&"undefined"!=typeof MARTAND_SUN_TEMPLE&&(n.innerHTML=`\n        <div class="martand-inner">\n            <div class="martand-content">\n                <h3>☀️ ${MARTAND_SUN_TEMPLE.title}</h3>\n                <p><strong>Commissioned:</strong> ${MARTAND_SUN_TEMPLE.builtYear}</p>\n                <p><strong>Architectural Synthesis:</strong> ${MARTAND_SUN_TEMPLE.architecturalStyle}</p>\n                <p><strong>Principal Deity:</strong> ${MARTAND_SUN_TEMPLE.deity}</p>\n                <ul class="highlights-list">\n                    ${MARTAND_SUN_TEMPLE.highlights.map(n=>`<li>✨ ${n}</li>`).join("")}\n                </ul>\n            </div>\n        </div>\n    `)}function renderCampaigns(){const n=document.getElementById("campaigns-grid");n&&"undefined"!=typeof CAMPAIGNS_AND_HISTORIOGRAPHY&&(n.innerHTML=CAMPAIGNS_AND_HISTORIOGRAPHY.map(n=>`\n        <div class="campaign-card">\n            <span class="category-tag">${n.category}</span>\n            <h3>📍 ${n.title}</h3>\n            <p>${n.detail}</p>\n        </div>\n    `).join(""))}function renderTimeline(){const n=document.getElementById("timeline-container");n&&"undefined"!=typeof TIMELINE_EVENTS&&(n.innerHTML=TIMELINE_EVENTS.map(n=>`\n        <div class="timeline-card">\n            <div class="timeline-year">${n.year}</div>\n            <div class="timeline-content">\n                <h3>${n.title}</h3>\n                <p>${n.description}</p>\n            </div>\n        </div>\n    `).join(""))}function renderReferences(){const n=document.getElementById("references-list");n&&"undefined"!=typeof REFERENCES&&(n.innerHTML=REFERENCES.map(n=>`\n        <li>\n            <a href="${n.link}" target="_blank" rel="noopener noreferrer">📚 ${n.text}</a>\n        </li>\n    `).join(""))}function initThemeToggle(){const n=document.getElementById("theme-toggle");n&&n.addEventListener("click",()=>{const e=document.body.classList.toggle("light-theme");localStorage.setItem("theme",e?"light":"dark"),n.textContent=e?"🌙":"☀️"})}document.addEventListener("DOMContentLoaded",()=>{renderStats(),renderMartandCard(),renderCampaigns(),renderTimeline(),renderReferences(),initThemeToggle()});